LADDER = [  # relaxed in this order; auth and Go never relax
    ("active_30d", {"range": {"last_active": {"gte": "now-30d"}}}),
    ("within_10km", {"geo_distance": {"distance": "10km",
                     "location": "40.75,-73.99"}}),
    ("years_8", {"range": {"years": {"gte": 8}}}),
]
MIN_HITS = 5

def search_with_relaxation(es, base_filters, soft_functions):
    relaxed = []
    for step in range(len(LADDER) + 1):
        hard = [f for name, f in LADDER[step:]]
        query = {"function_score": {
            "query": {"bool": {"filter": base_filters + hard}},
            "functions": soft_functions,
            "score_mode": "sum", "boost_mode": "replace"}}
        resp = es.search(index="candidates", query=query)
        if resp["hits"]["total"]["value"] >= MIN_HITS:
            break
        if step < len(LADDER):
            relaxed.append(LADDER[step][0])
    return resp, relaxed   # show relaxed to the user
